#include <iostream>

#include <queue>

using namespace std;

struct HuffmanNode {

    char ch;

    int freq;

    HuffmanNode* left;

    HuffmanNode* right;



    HuffmanNode(char c, int f) : ch(c), freq(f), 

                                  left(nullptr), right(nullptr) {}

};

struct Compare {

    bool operator()(HuffmanNode* a, HuffmanNode* b) {

        return a->freq > b->freq;

    }

};

HuffmanNode* buildHuffmanTree(char chars[], int freqs[], int n) {

    priority_queue<HuffmanNode*, vector<HuffmanNode*>, 

                   Compare> minHeap;



    for (int i = 0; i < n; i++) {

        minHeap.push(new HuffmanNode(chars[i], freqs[i]));

    }



    while (minHeap.size() > 1) {

        HuffmanNode* left = minHeap.top();

        minHeap.pop();

        HuffmanNode* right = minHeap.top();

        minHeap.pop();



        HuffmanNode* parent = new HuffmanNode('\0', 

            left->freq + right->freq);

        parent->left = left;

        parent->right = right;

        minHeap.push(parent);

    }



    return minHeap.top();

}

