class HuffmanNode {

    constructor(ch, freq) {

        this.ch = ch;

        this.freq = freq;

        this.left = null;

        this.right = null;

    }

}

class MinHeap {

    constructor() {

        this.heap = [];

    }



    push(node) {

        this.heap.push(node);

        this.bubbleUp(this.heap.length - 1);

    }



    pop() {

        if (this.heap.length === 0) return null;

        const min = this.heap[0];

        this.heap[0] = this.heap[this.heap.length - 1];

        this.heap.pop();

        this.bubbleDown(0);

        return min;

    }



    bubbleUp(idx) {

        while (idx > 0) {

            const parentIdx = Math.floor((idx - 1) / 2);

            if (this.heap[idx].freq < this.heap[parentIdx].freq) {

                [this.heap[idx], this.heap[parentIdx]] = 

                    [this.heap[parentIdx], this.heap[idx]];

                idx = parentIdx;

            } else break;

        }

    }



    bubbleDown(idx) {

        const n = this.heap.length;

        while (2 * idx + 1 < n) {

            let smallestIdx = idx;

            const left = 2 * idx + 1;

            const right = 2 * idx + 2;

            if (this.heap[left].freq < this.heap[smallestIdx].freq)

                smallestIdx = left;

            if (right < n && this.heap[right].freq < 

                this.heap[smallestIdx].freq)

                smallestIdx = right;

            if (smallestIdx !== idx) {

                [this.heap[idx], this.heap[smallestIdx]] = 

                    [this.heap[smallestIdx], this.heap[idx]];

                idx = smallestIdx;

            } else break;

        }

    }



    size() {

        return this.heap.length;

    }

}

function buildHuffmanTree(chars, freqs) {

    const minHeap = new MinHeap();

    for (let i = 0; i < chars.length; i++) {

        minHeap.push(new HuffmanNode(chars[i], freqs[i]));

    }



    while (minHeap.size() > 1) {

        const left = minHeap.pop();

        const right = minHeap.pop();

        const parent = new HuffmanNode(null, 

            left.freq + right.freq);

        parent.left = left;

        parent.right = right;

        minHeap.push(parent);

    }



    return minHeap.pop();

}

